{"PANDA": "import pandas as pd

def convert_type(value):
    if pd.isna(value):
        return value
    if isinstance(value, (int, float)):
        return value
    s = str(value).strip()
    # Try to convert to int or float
    try:
        if '.' in s:
            return float(s.replace(',', ''))
        else:
            return int(s.replace(',', ''))
    except ValueError:
        pass
    # Try to convert to date
    for fmt in ['%Y', '%Y-%m-%d', '%d/%m/%Y', '%m/%d/%Y']:
        try:
            return pd.to_datetime(s, format=fmt)
        except ValueError:
            continue
    return s

def find_word(word):
    return word

# Extract country codes from Men's winner and Women's winner columns
