{"PANDA": "import pandas as pd
def find_max_consecutive_wins(df):
    # Filter rows where Result starts with 'W' (win)
    wins = df[df['Result'].str.startswith('W')].reset_index(drop=True)
    if len(wins) == 0:
        return 0

    max_streak = 1
    current_streak = 1

    for i in range(1, len(wins)):
        if wins.loc[i, 'Opponent'] == wins.loc[i-1, 'Opponent']:
            current_streak += 1
            max_streak = max(max_streak, current_streak)
        else:
            current_streak = 1

    return max_streak

find_max_consecutive_wins(df)"}
